<?php  use App\Models\Donasi; use App\Models\ProfilDonatur; use App\Models\User;  beforeEach(function () {     $this->ketua = User::factory()->create([         'role' => 'ketua',         'status' => 'aktif',     ]); });  test('ketua can view donatur list', function () {     $donatur = User::factory()->create([         'role' => 'donatur',         'username' => 'donatur.setia',     ]);     ProfilDonatur::create([         'user_id' => $donatur->id,         'nama' => 'Hamba Allah',         'no_hp' => '081234567890',     ]);      $response = $this->actingAs($this->ketua)->get(route('ketua.donatur.index'));      $response->assertOk();     $response->assertSee('Hamba Allah');     $response->assertSee('donatur.setia'); });  test('ketua can search donatur by name or username', function () {     $donatur1 = User::factory()->create([         'role' => 'donatur',         'username' => 'andi_donatur',     ]);     ProfilDonatur::create([         'user_id' => $donatur1->id,         'nama' => 'Andi Wijaya',     ]);      $donatur2 = User::factory()->create([         'role' => 'donatur',         'username' => 'budi_donatur',     ]);     ProfilDonatur::create([         'user_id' => $donatur2->id,         'nama' => 'Budi Pratama',     ]);      $response = $this->actingAs($this->ketua)->get(route('ketua.donatur.index', ['search' => 'Andi']));      $response->assertOk();     $response->assertSee('Andi Wijaya');     $response->assertDontSee('Budi Pratama'); });  test('ketua can view donatur detail and donation history', function () {     $donatur = User::factory()->create([         'role' => 'donatur',     ]);     ProfilDonatur::create([         'user_id' => $donatur->id,         'nama' => 'Siti Nurhaliza',         'no_hp' => '081234567899',         'alamat' => 'Jl. Anggrek 1',     ]);      Donasi::create([         'kode_donasi' => 'DON-KETUA-001',         'nama_donatur' => 'Siti Nurhaliza',         'email' => $donatur->email,         'nominal' => 250000,         'tanggal' => now(),         'status' => 'diterima',         'metode_pembayaran' => 'transfer',         'donatur_id' => $donatur->id,     ]);      $response = $this->actingAs($this->ketua)->get(route('ketua.donatur.show', $donatur));      $response->assertOk();     $response->assertSee('Siti Nurhaliza');     $response->assertSee('DON-KETUA-001'); });  test('ketua gets 404 when viewing non donatur user on donatur show', function () {     $nonDonatur = User::factory()->create([         'role' => 'admin',     ]);      $response = $this->actingAs($this->ketua)->get(route('ketua.donatur.show', $nonDonatur));      $response->assertNotFound(); });  test('non ketua user cannot access ketua donatur module', function () {     $donatur = User::factory()->create([         'role' => 'donatur',     ]);      $response = $this->actingAs($donatur)->get(route('ketua.donatur.index'));      $response->assertForbidden(); });